{"id": "open_logan_paul_channel", "name": "Open Logan Paul's YouTube Channel", "type": "sequential", "steps": [
  {"tool": "fetch_page", "args": {"url": "https://www.youtube.com/@LoganPaul"}, "store_result_as": "$page"},
  {"type": "conditional",
   "condition": {"field": "$page.status_code", "operator": ">=", "value": 400},
   "if_true": {"type": "sequential", "steps": [
     {"tool": "web_search", "args": {"query": "Logan Paul official YouTube channel"}, "store_result_as": "$search_results"},
     {"tool": "llm_summarise", "args": {"prompt": "Select the URL of Logan Paul's official YouTube channel from these results.", "context": "$search_results"}, "store_result_as": "$best_url"},
     {"tool": "app_open", "args": {"target": "$best_url"}}
   ]},
   "if_false": {"tool": "app_open", "args": {"target": "https://www.youtube.com/@LoganPaul"}}
  }
]}

